function employeeForUser(){
 global $c;
 $s=$c->prepare('SELECT * FROM employees WHERE username=? LIMIT 1');$u=$_SESSION['username'];$s->bind_param('s',$u);$s->execute();return $s->get_result()->fetch_assoc();
}
function canAdminWriteOnly(){return ($_SESSION['role']??'')==='admin';}
function saveUploadedImage($field,$folder){
 if(empty($_FILES[$field]) || $_FILES[$field]['error']===UPLOAD_ERR_NO_FILE) return '';
 if($_FILES[$field]['error']!==UPLOAD_ERR_OK) jsonResponse(false,'Image upload failed.',[],422);
 if($_FILES[$field]['size']>3*1024*1024) jsonResponse(false,'Image must be 3 MB or smaller.',[],422);
 $info=@getimagesize($_FILES[$field]['tmp_name']);
 if(!$info || !in_array($info['mime'],['image/jpeg','image/png','image/webp'],true)) jsonResponse(false,'Only JPG, PNG or WEBP images are allowed.',[],422);
 $dir=dirname(__DIR__).'/uploads/'.$folder; if(!is_dir($dir)) @mkdir($dir,0775,true);
 $ext=$info['mime']==='image/png'?'png':($info['mime']==='image/webp'?'webp':'jpg');
 $name=bin2hex(random_bytes(12)).'.'.$ext; if(!move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$name)) jsonResponse(false,'Could not save uploaded image.',[],500);
 return 'uploads/'.$folder.'/'.$name;
}

if($action==='me'){jsonResponse(true,'',['user'=>currentUser()]);}

if($action==='dashboard_stats'){
 $role=$_SESSION['role'];
 $today=date('Y-m-d');$month=date('Y-m');
 $stats=['employees'=>0,'orders'=>0,'stock_items'=>0,'income'=>0,'expense'=>0,'revenue'=>0,'attendance'=>0,'suppliers'=>0];
 $r=$c->query("SELECT COUNT(*) n FROM employees WHERE status='Active'");$stats['employees']=(int)$r->fetch_assoc()['n'];
 $r=$c->query("SELECT COUNT(*) n FROM orders WHERE DATE(created_at)=CURDATE()");$stats['orders']=(int)$r->fetch_assoc()['n'];
 $r=$c->query("SELECT COUNT(*) n FROM inventory");$stats['stock_items']=(int)$r->fetch_assoc()['n'];
 $r=$c->query("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) expense FROM transactions WHERE DATE_FORMAT(transaction_date,'%Y-%m')='$month'");$x=$r->fetch_assoc();$stats['income']=(float)$x['income'];$stats['expense']=(float)$x['expense'];$stats['revenue']=$stats['income']-$stats['expense'];
 $r=$c->query("SELECT COUNT(*) n FROM attendance WHERE work_date='$today'");$stats['attendance']=(int)$r->fetch_assoc()['n'];
 $r=$c->query("SELECT COUNT(*) n FROM suppliers WHERE status='Active'");$stats['suppliers']=(int)$r->fetch_assoc()['n'];
 $r=$c->query('SELECT id,title,details,module,created_at FROM updates_feed ORDER BY id DESC LIMIT 8');$updates=$r->fetch_all(MYSQLI_ASSOC);
 jsonResponse(true,'',['stats'=>$stats,'updates'=>$updates]);
}

