if($action==='attendance'){
 requireRole(['moderator','accounts','inventory','hr','executive']);$emp=employeeForUser();if(!$emp)jsonResponse(false,'No employee record is linked to this login.',[],422);$today=date('Y-m-d');
 $q=$c->prepare('SELECT * FROM attendance WHERE employee_id=? AND work_date=?');$q->bind_param('is',$emp['id'],$today);$q->execute();$row=$q->get_result()->fetch_assoc();
 if(!$row){$st='Present';$ins=$c->prepare('INSERT INTO attendance(employee_id,work_date,status) VALUES(?,?,?)');$ins->bind_param('iss',$emp['id'],$today,$st);$ins->execute();$q->execute();$row=$q->get_result()->fetch_assoc();}
 $event=clean($_POST['event']??'');$now=date('Y-m-d H:i:s');
