 elseif($event==='resume' && $row['break_start'] && !$row['break_end']){$s=$c->prepare('UPDATE attendance SET break_end=?,break_minutes=TIMESTAMPDIFF(MINUTE,break_start,?) WHERE id=?');$s->bind_param('ssi',$now,$now,$row['id']);$s->execute();}
 elseif($event==='checkout' && $row['check_in'] && !$row['check_out']){$s=$c->prepare('UPDATE attendance SET check_out=?,work_minutes=TIMESTAMPDIFF(MINUTE,check_in,?)-break_minutes WHERE id=?');$s->bind_param('ssi',$now,$now,$row['id']);$s->execute();}
 else jsonResponse(false,'That attendance action is not available for the current state.',[],422);
 jsonResponse(true,'Attendance updated.');
}
