 requireRole(['moderator','executive']);$text=clean($_POST['text']??'');if(!$text)jsonResponse(false,'Enter an order message.',[],422);
 $key=envv('OPENAI_API_KEY');$data=null;
 if($key){
   $model=envv('OPENAI_MODEL')?:'gpt-5.6-luna';
   $payload=['model'=>$model,'input'=>'Extract this customer order into JSON. Return ONLY JSON with keys customer_name,mobile,address,product,quantity,unit_price,package_type,delivery_date,notes. Unknown values should be null. Order: '.$text];
   $ch=curl_init('https://api.openai.com/v1/responses');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>40]);$out=curl_exec($ch);$err=curl_error($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
   if(!$err && $code>=200 && $code<300){$j=json_decode($out,true);$raw=$j['output'][0]['content'][0]['text']??'';$raw=preg_replace('/^```(?:json)?|```$/m','',trim($raw));$data=json_decode($raw,true);}
 }
 if(!$data){
   // Local fallback keeps the feature usable before an API key is configured.
   $data=['customer_name'=>null,'mobile'=>null,'address'=>null,'product'=>null,'quantity'=>1,'unit_price'=>0,'package_type'=>null,'delivery_date'=>null,'notes'=>$text];
   if(preg_match('/(?:customer|name)\s*[:=-]\s*([^,;\n]+)/i',$text,$m))$data['customer_name']=trim($m[1]);
   elseif(preg_match('/^\s*([^,;\n]{2,60})\s*,/',$text,$m))$data['customer_name']=trim($m[1]);
   if(preg_match('/01\d{9}/',$text,$m))$data['mobile']=$m[0];
   if(preg_match('/(\d+(?:\.\d+)?)\s*(?:pcs|pieces|bags|units|qty)/i',$text,$m))$data['quantity']=(float)$m[1];
   if(preg_match('/(?:cash|total|amount)\s*[:=-]?\s*(?:৳|tk)?\s*(\d+(?:\.\d+)?)/i',$text,$m))$data['unit_price']=(float)$m[1]/max(1,(float)$data['quantity']);
   if(preg_match('/(?:address|deliver to|delivery)\s*[:=-]\s*([^;\n]+)/i',$text,$m))$data['address']=trim($m[1]);
   if(preg_match('/(?:product|item)\s*[:=-]\s*([^,;\n]+)/i',$text,$m))$data['product']=trim($m[1]);
   if(!$data['customer_name'] && !$data['mobile'] && !$data['address'])jsonResponse(false,'AI is not configured. Add OPENAI_API_KEY for full AI extraction, or use a message containing clear labels such as customer:, mobile:, address:, product:, quantity: and amount:.',[],503);
 }
 jsonResponse(true,$key?'AI extracted the order.':'Order parsed with local fallback. Add OPENAI_API_KEY for full AI extraction.',['order'=>$data]);
}

